TYPO03_agentic_grep_5e277171.final_sparql:
PREFIX oriont: <https://orienting.eu/oriont#>

SELECT ?activity ?inputFlows ?outputFlows
WHERE {
  {
    SELECT ?activity (GROUP_CONCAT(DISTINCT STR(?inputFlow); SEPARATOR=" | ") AS ?inputFlows)
    WHERE {
      ?inputFlow oriont:isInputOf ?activity .
    }
    GROUP BY ?activity
  }
  {
    SELECT ?activity (GROUP_CONCAT(DISTINCT STR(?outputFlow); SEPARATOR=" | ") AS ?outputFlows)
    WHERE {
      ?outputFlow oriont:isOutputOf ?activity .
    }
    GROUP BY ?activity
  }
}
ORDER BY ?activity

TYPO03_agentic_grep_5e277171.gt_sparql:
PREFIX oriont: <https://orienting.eu/oriont#>
PREFIX oriont-ext: <https://orienting.eu/oriont-ext#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?activity ?activityLabel ?flow ?flowName ?value ?unit WHERE {
    ?activity a oriont:Activity .
    ?activity rdfs:label ?activityLabel .
    { ?flow oriont:isInputOf ?activity } UNION { ?flow oriont:isOutputOf ?activity }
    OPTIONAL { ?flow oriont-ext:hasFlowName ?flowName }
    OPTIONAL { ?flow oriont-ext:hasMeasureValue ?value }
    OPTIONAL { ?flow oriont-ext:hasMeasureUnit ?unit }
}

